def recall_at_k(retrieved_ids, relevant_ids, k):
    rel = set(relevant_ids)
    if not rel:
        return 0.0
    hits = sum(1 for d in retrieved_ids[:k] if d in rel)
    return hits / len(rel)

def rrf_fuse(rankings, k=60):
    from collections import defaultdict
    s = defaultdict(float)
    for r in rankings:
        for rank, doc in enumerate(r):
            s[doc] += 1.0 / (k + rank + 1)
    return sorted(s, key=lambda d: s[d], reverse=True)
